type InventoryGateway interface {  // contract the caller sees
	CheckStock(ctx context.Context, sku string) (Stock, error)
}
type natsInventory struct{ conn *nats.Conn }     // owns the transport
func (g *natsInventory) CheckStock(ctx context.Context, sku string) (Stock, error) {
	msg, err := g.conn.Request("orders.inventory.check", []byte(sku), 2*time.Second)
	if err != nil {  // nats.ErrNoResponders | nats.ErrTimeout
		return Stock{}, fmt.Errorf("inventory: %w", err)
	}
	var s Stock
	return s, json.Unmarshal(msg.Data, &s)
}
